{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.cp_1 AS WITH clickpost_base AS ( SELECT co.*, CASE WHEN LOWER(\"Courier Partner\") LIKE \'%reverse%\' THEN \'Reverse\' ELSE \'Forward\' END AS \"Mode\" FROM snitch_db.maplemonk.snitch_clickpost_track_order_dashboard_report co ), zone_mot_mapping AS ( SELECT DISTINCT TRY_TO_NUMBER(\"Pickup Pin\"::VARCHAR) AS pickup_pin, TRY_TO_NUMBER(\"Drop Pin\"::VARCHAR) AS drop_pin, UPPER(TRIM(Zone::VARCHAR)) AS zone, TRIM(\"MOT\"::VARCHAR) AS mot, LOWER(TRIM(\"Courier Partner\"::VARCHAR)) AS courier_partner FROM snitch_db.maplemonk.pincodemappingzonemot ), geo_mapping AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY delivery_postcode ORDER BY 1 ) AS rw FROM snitch_db.maplemonk.pincodemappingzoneupdatedsnitch ) WHERE rw = 1 ), final AS ( SELECT *, CASE WHEN PIN_code LIKE \'11%\' THEN \'Delhi\' WHEN PIN_code LIKE \'12%\' OR PIN_code LIKE \'13%\' THEN \'Haryana\' WHEN PIN_code LIKE \'14%\' OR PIN_code LIKE \'15%\' THEN \'Punjab\' WHEN PIN_code LIKE \'16%\' THEN \'Chandigarh\' WHEN PIN_code LIKE \'17%\' THEN \'Himachal Pradesh\' WHEN PIN_code LIKE \'18%\' OR PIN_code LIKE \'19%\' THEN \'Jammu and Kashmir, Ladakh\' WHEN PIN_code BETWEEN \'200000\' AND \'289999\' THEN \'Uttar Pradesh, Uttarakhand\' WHEN PIN_code BETWEEN \'300000\' AND \'349999\' THEN \'Rajasthan\' WHEN PIN_code BETWEEN \'360000\' AND \'399999\' AND PIN_code NOT LIKE \'396%\' THEN \'Gujarat\' WHEN PIN_code LIKE \'396%\' THEN \'Dadra & Nagar Haveli and Daman & Diu\' WHEN PIN_code BETWEEN \'400000\' AND \'449999\' AND PIN_code NOT LIKE \'403%\' THEN \'Maharashtra\' WHEN PIN_code LIKE \'403%\' THEN \'Goa\' WHEN PIN_code BETWEEN \'450000\' AND \'489999\' THEN \'Madhya Pradesh\' WHEN PIN_code LIKE \'49%\' THEN \'Chhattisgarh\' WHEN PIN_code LIKE \'50%\' THEN \'Telangana\' WHEN PIN_code BETWEEN \'510000\' AND \'539999\' THEN \'Andhra Pradesh\' WHEN PIN_code BETWEEN \'560000\' AND \'599999\' THEN \'Karnataka\' WHEN PIN_code BETWEEN \'600000\' AND \'669999\' THEN \'Tamil Nadu\' WHEN PIN_code LIKE \'605%\' THEN \'Puducherry\' WHEN PIN_code BETWEEN \'670000\' AND \'699999\' AND PIN_code NOT LIKE \'682%\' THEN \'Kerala\' WHEN PIN_code LIKE \'682%\' THEN \'Lakshadweep\' WHEN PIN_code BETWEEN \'700000\' AND \'749999\' AND PIN_code NOT LIKE \'737%\' AND PIN_code NOT LIKE \'744%\' THEN \'West Bengal\' WHEN PIN_code LIKE \'737%\' THEN \'Sikkim\' WHEN PIN_code LIKE \'744%\' THEN \'Andaman and Nicobar Islands\' WHEN PIN_code BETWEEN \'750000\' AND \'779999\' THEN \'Odisha\' WHEN PIN_code LIKE \'78%\' THEN \'Assam\' WHEN PIN_code BETWEEN \'790000\' AND \'799999\' THEN \'Arunachal Pradesh\' WHEN PIN_code BETWEEN \'793000\' AND \'794999\' THEN \'Meghalaya\' WHEN PIN_code LIKE \'795%\' THEN \'Manipur\' WHEN PIN_code LIKE \'796%\' THEN \'Mizoram\' WHEN PIN_code BETWEEN \'797000\' AND \'798999\' THEN \'Nagaland\' WHEN PIN_code LIKE \'799%\' THEN \'Tripura\' WHEN PIN_code BETWEEN \'800000\' AND \'859999\' THEN \'Bihar, Jharkhand\' WHEN PIN_code BETWEEN \'900000\' AND \'999999\' THEN \'Army Postal Service\' ELSE \'Unknown\' END AS final_State FROM ( SELECT awb AS awb_number, TRY_TO_TIMESTAMP( \"Created at\", \'YYYY-MM-DD HH24:MI:SS\' ) AS assigned_date, TRY_TO_TIMESTAMP( \"Order Date\", \'YYYY-MM-DD HH24:MI:SS\' ) AS ORDER_DATE_dummy, \"Pickup Date\", TRY_TO_TIMESTAMP( \"Pickup Date\", \'YYYY-MM-DD HH24:MI:SS\' ) AS PICKUP_DATE, TRY_TO_TIMESTAMP( \"Delivery Date\", \'YYYY-MM-DD HH24:MI:SS\' ) AS DELIVERY_DATE, \"Current Location\" AS Current_Location, TRY_TO_TIMESTAMP( \"Latest Timestamp\", \'YYYY-MM-DD HH24:MI:SS\' ) AS LATEST_TIMESTAMP, \"Latest Remark\" AS Latest_Remark, \"Clickpost Unified Status\" AS pre_current_status, CASE WHEN LOWER(pre_current_status) IN ( \'rto-shipmentdelay\', \'rto-delivered\', \'rto-intransit\', \'rto-requested\', \'rto-marked\', \'rto-contactcustomercare\', \'rto-outfordelivery\', \'rto-failed\' ) THEN \'RTO\' WHEN LOWER(pre_current_status) IN ( \'pickedup\', \'destinationhubin\', \'contactcustomercare\', \'shipmentdelayed\', \'origincityin\', \'outfordelivery\', \'intransit\', \'origincityout\', \'shipmentheld\' ) THEN \'INTRANSIT\' WHEN LOWER(pre_current_status) IN (\'delivered\') THEN \'DELIVERED\' WHEN LOWER(pre_current_status) IN (\'cancelled\') THEN \'CANCELLED\' WHEN LOWER(pre_current_status) IN ( \'orderplaced\', \'outforpickup\', \'awb registered\', \'pickuppending\', \'pickupfailed\' ) THEN \'ORDER_PLACED\' WHEN LOWER(pre_current_status) IN ( \'faileddelivery\', \'notserviceable\' ) THEN \'UNDELIVERED\' WHEN LOWER(pre_current_status) IN ( \'lost\', \'damaged\' ) THEN \'LOST\' END AS status, \"Order ID\" AS ORDER_ID, \"Product SKU Code\" SKU_LIST, \"Items Quantity\" quantity_in_Box, \"Out For Delivery Attempts\" AS Out_For_Delivery_Attempts, CASE WHEN LOWER(\"Courier Partner\") LIKE \'%hld%\' THEN TRY_TO_TIMESTAMP( \"Delivery Date\", \'YYYY-MM-DD HH24:MI:SS\' ) ELSE TRY_TO_TIMESTAMP( \"Out For Delivery 1st Attempt\", \'YYYY-MM-DD HH24:MI:SS\' ) END AS outfordelivery_date, \"Courier Partner\" AS COURIER_PARTNER, \"Shipment Weight\", TRY_CAST( \"Expected Date of Delivery (Max)\" AS DATE ) AS MAX_SLA, TRY_CAST( \"Expected Date of Delivery (Min)\" AS DATE ) AS MIN_SLA, \"Expected delivery date by Courier Partner\" EDD_CP, \"Payment Mode\" AS PAYMENT_MODE, \"Payment Mode\" AS PAYMENT_METHOD, \"Invoice Date\" AS INVOICE_DATE, \"Invoice Value\" AS INVOICE_VALUE, \"Invoice Number\" AS INVOICE_NUMBER, \"Drop Pincode\" AS pincode, \"Drop City\" CITY, \"Drop State\" STATE, \"Drop Name\" Customer_name, \"Drop Phone\" PHONE, \"Drop Email\" EMAIL, DATEDIFF( \'hour\', pickup_date, outfordelivery_date ) AS P2A, DATEDIFF( \'hour\', pickup_date, delivery_date ) AS P2D, ( DATEDIFF( \'hour\', ORDER_DATE_dummy, pickup_date ) / 24 )::INT AS O2P1, ( DATEDIFF( \'hour\', ORDER_DATE_dummy, assigned_date ) / 24 )::INT AS O2A1, CASE WHEN delivery_date::DATE >= MIN_SLA AND delivery_date::DATE <= MAX_SLA THEN 1 ELSE 0 END AS in_time, CASE WHEN o2p1 = 0 THEN \'D-0\' WHEN o2p1 = 1 THEN \'D-1\' WHEN o2p1 = 2 THEN \'D-2\' WHEN o2p1 = 3 THEN \'D-3\' WHEN o2p1 > 3 THEN \'3+\' END AS O2P, CASE WHEN o2A1 = 0 THEN \'D-0\' WHEN o2A1 = 1 THEN \'D-1\' WHEN o2A1 = 2 THEN \'D-2\' WHEN o2A1 = 3 THEN \'D-3\' WHEN o2A1 > 3 THEN \'3+\' END AS O2A, CASE WHEN outfordelivery_date::DATE = delivery_date::DATE THEN 1 WHEN outfordelivery_date::DATE != delivery_date::DATE THEN 0 END AS FASR, \"Reference Number\", CASE WHEN \"Pickup Pincode\" = \'122105\' AND UPPER(TRIM(\"Mode\")) = \'FORWARD\' THEN \'TAURU\' WHEN \"Reference Number\" LIKE \'%EMIZA%\' THEN \'EMIZA\' WHEN \"Reference Number\" LIKE \'%WH1%\' THEN \'YLK1\' WHEN \"Reference Number\" LIKE \'%SAPL%\' THEN \'YLK2\' WHEN \"Reference Number\" LIKE \'%INV-SR%\' THEN \'HSK\' WHEN \"Reference Number\" LIKE \'%OMNI%\' THEN \'OMNI\' WHEN LOWER(\"Courier Partner\") LIKE \'%hld%\' THEN \'Qcom\' ELSE NULL END AS warehouse, mapped_zone AS zone, UPPER( TRIM(delivery_state) ) AS mapped_state, UPPER( TRIM(delivery_city) ) AS mapped_city, NULLIF( \"RTO Mark Date\", \'\' )::DATE AS RTO_MARK_DATE, NULLIF( \"Out For Pickup Attempts\", \'\' )::DATE AS OFP_ATTEMPTS, NULLIF( \"Out For Pickup 1st Attempt\", \'\' )::DATE AS OFP_1_ATTEMPT, NULLIF( \"Out For Pickup 2nd Attempt\", \'\' )::DATE AS OFP_2_ATTEMPT, NULLIF( \"Out For Pickup 3rd Attempt\", \'\' )::DATE AS OFP_3_ATTEMPT, NULLIF( \"Reason For First Failed Pickup\", \'\' )::STRING AS RVP_FAIL_REASON, NULLIF( \"Reason For First Failed Delivery\", \'\' )::STRING AS FAILED_DEL_REASON, NULLIF( \"Reason For Last Failed Delivery\", \'\' )::STRING AS LAST_FAILED_DEL_REASON, NULLIF( \"TimeStamp Of Last Failed Delivery\", \'\' )::DATE AS LAST_FAILED_DELIVERY, CASE WHEN UPPER(TRIM(\"Mode\")) = \'REVERSE\' THEN \"Pickup Pincode\" ELSE \"Drop Pincode\" END AS PIN_code, CASE WHEN UPPER(TRIM(\"Mode\")) = \'REVERSE\' THEN \"Drop Pincode\" ELSE \"Pickup Pincode\" END AS PICKUP_PINCODE, CASE WHEN LOWER(\"Courier Partner\") LIKE \'delhivery%\' THEN \'Delhivery\' WHEN LOWER(\"Courier Partner\") LIKE \'bluedart%\' THEN \'Bluedart\' WHEN LOWER(\"Courier Partner\") LIKE \'blitz%\' THEN \'Blitz\' WHEN LOWER(\"Courier Partner\") LIKE \'shirocket%\' THEN \'Shiprocket\' WHEN LOWER(\"Courier Partner\") LIKE \'proship%\' THEN \'Proship\' ELSE \'Snitch\' END AS wh, CASE WHEN UPPER(TRIM(\"Mode\")) = \'REVERSE\' THEN \"RVP Reason\" ELSE NULL END AS Return_Reason, \"Mode\" AS Mode, CASE WHEN UPPER(TRIM(\"Mode\")) = \'FORWARD\' AND LOWER(\"Clickpost Unified Status\") LIKE \'%rto%\' THEN \'RTO\' WHEN UPPER(TRIM(\"Mode\")) = \'REVERSE\' THEN \'Reverse\' ELSE \'Forward\' END AS journey, CASE WHEN LOWER(\"Account Code\") LIKE \'%bharatdart%\' THEN \'Surface\' WHEN LOWER(\"Courier Partner\") LIKE \'bluedart%\' THEN CASE WHEN UPPER(TRIM(mapped_zone)) IN (\'A\', \'B\') THEN \'Surface\' ELSE \'Air\' END ELSE mapped_mot END AS MODE_1, CASE WHEN LOWER(\"Courier Partner\") LIKE \'delhivery%\' THEN \'Delhivery\' WHEN LOWER(\"Courier Partner\") LIKE \'proship%\' THEN \'Proship\' WHEN LOWER(\"Courier Partner\") LIKE \'blitz%\' THEN \'Blitz (Formerly Grow Simplee)\' ELSE \"Courier Partner\" END AS Partner FROM ( SELECT co.*, zm.zone AS mapped_zone, zm.mot AS mapped_mot, gm.delivery_state, gm.delivery_city FROM clickpost_base co LEFT JOIN zone_mot_mapping zm ON TRY_TO_NUMBER( CASE WHEN UPPER(TRIM(co.\"Mode\")) = \'REVERSE\' THEN co.\"Drop Pincode\"::VARCHAR ELSE co.\"Pickup Pincode\"::VARCHAR END ) = zm.pickup_pin AND TRY_TO_NUMBER( CASE WHEN UPPER(TRIM(co.\"Mode\")) = \'REVERSE\' THEN co.\"Pickup Pincode\"::VARCHAR ELSE co.\"Drop Pincode\"::VARCHAR END ) = zm.drop_pin AND ( CASE WHEN LOWER(co.\"Account Code\") LIKE \'%bharatdart%\' THEN \'bharatdart\' WHEN LOWER(co.\"Courier Partner\") LIKE \'bluedart%\' THEN \'bluedart\' WHEN LOWER(co.\"Courier Partner\") LIKE \'delhivery%\' THEN \'delhivery\' WHEN LOWER(co.\"Courier Partner\") LIKE \'blitz%\' THEN \'blitz\' WHEN LOWER(co.\"Courier Partner\") LIKE \'shiprocket%\' OR LOWER(co.\"Courier Partner\") LIKE \'shirocket%\' THEN \'shiprocket\' WHEN LOWER(co.\"Courier Partner\") LIKE \'shadowfax%\' THEN \'shadowfax\' WHEN LOWER(co.\"Courier Partner\") LIKE \'ekart%\' THEN \'ekart\' WHEN LOWER(co.\"Courier Partner\") LIKE \'urbanbolt%\' OR LOWER(co.\"Courier Partner\") LIKE \'urbonebolt%\' THEN \'urbanbolt\' ELSE LOWER( TRIM(co.\"Courier Partner\") ) END ) = zm.courier_partner LEFT JOIN geo_mapping gm ON TRY_TO_NUMBER( CASE WHEN UPPER(TRIM(co.\"Mode\")) = \'REVERSE\' THEN co.\"Pickup Pincode\"::VARCHAR ELSE co.\"Drop Pincode\"::VARCHAR END ) = TRY_TO_NUMBER( gm.delivery_postcode::VARCHAR ) ) ) ), ops AS ( SELECT final.*, final.zone AS final_zone FROM final ), correct_order_date AS ( SELECT * FROM ( SELECT awb, order_name, uc_created AS order_date, ROW_NUMBER() OVER ( PARTITION BY order_name ORDER BY order_timestamp DESC ) AS rn FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate ) WHERE rn = 1 ), package1 AS ( SELECT a.*, COALESCE( b.order_date, a.ORDER_DATE_dummy ) AS order_date FROM ops a LEFT JOIN correct_order_date b ON a.order_id = b.order_name ), uc_package AS ( SELECT DISTINCT awb, order_name, shipping_package_type, SUM(delay_flag) AS delay_flag, COUNT(saleorderitemcode) AS qty FROM snitch_db.maplemonk.warehouse_sla_performance WHERE sla_status NOT IN (\'CANCELLED\') AND marketplace_mapped IN (\'SHOPIFY\') AND sla_status IN ( \'BREACHED\', \'WITHIN SLA\' ) GROUP BY 1, 2, 3 ORDER BY qty DESC ), app AS ( SELECT shopify_order_number, TO_DATE( TRY_TO_TIMESTAMP_NTZ(max_edd) ) AS app1_edd FROM snitch_db.maplemonk.app_edd_data ), speedcheck AS ( SELECT COALESCE( a.app1_edd, ( order_date::DATE + ( max_sla::DATE - pickup_date::DATE ) )::DATE ) AS APP_EDD, package1.*, uc_package.shipping_package_type, delay_flag FROM package1 LEFT JOIN uc_package ON package1.awb_number = uc_package.awb LEFT JOIN app a ON package1.order_id = a.shopify_order_number ) SELECT CASE WHEN warehouse IS NULL AND TIMESTAMPDIFF( day, order_date, app_edd ) <= 1 THEN \'Speed\' ELSE \'Normal\' END AS Priority, * FROM speedcheck ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
